import numpy as np
from numba import njit

@njit(cache=True, fastmath=True)
def heat_step(u, alpha):
    new = u.copy()
    for i in range(1, u.shape[0]-1):
        for j in range(1, u.shape[1]-1):
            new[i, j] = u[i, j] + alpha * (
                u[i+1, j] + u[i-1, j] + u[i, j+1] + u[i, j-1] - 4*u[i, j]
            )
    return new

